public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) return null;
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    buildTypeVariableMap(targetType, targetType, typeVarMap);
    Class<?>[] result = new Class<?>[args.length];
    for (int i=0;i<args.length;i++){
        Type arg = args[i];
        if (arg instanceof TypeVariable){
            Type resolved = typeVarMap.get(arg);
            if (resolved instanceof Class){
                result[i] = (Class<?>) resolved;
            } else if (resolved instanceof ParameterizedType){
                result[i] = (Class<?>) ((ParameterizedType) resolved).getRawType();
            } else {
                return null;
            }
        } else if (arg instanceof Class){
            result[i] = (Class<?>) arg;
